H.background();
// Speed of sound in air:  v = sqrt(gamma * R * T / M)
// gamma = 1.4 (diatomic), R = 8.314 J/mol/K, M = 0.029 kg/mol for air.
// Slide temperature T (Kelvin) and watch the pulse cross a 340 m field.
const T = Math.max(1, P.T);
const gamma = 1.4, R = 8.314, M = 0.029;
const vs = Math.sqrt(gamma * R * T / M);     // speed of sound (m/s)
const D = 340;                                // field length (m)
const flight = D / vs;                        // time of flight (s)
const v = H.plot2d({ xMin: 0, xMax: D, yMin: -1, yMax: 1 });
v.grid({ stepX: 100 }); v.axes({ stepX: 100 });
// emitter at x=0, listener at x=340; pulse loops across the field
const period = flight + 0.4;                  // pause before re-firing
const phase = t % period;
const xp = Math.min(D, vs * phase);           // pulse position (m)
// expanding wavefront ring drawn as a vertical pressure spike
v.line(xp, -0.8, xp, 0.8, { color: H.colors.warn, width: 3 });
v.dot(xp, 0, { r: 6, fill: H.colors.warn });
// fixed markers: speaker and ear
v.dot(0, 0, { r: 8, fill: H.colors.accent });
v.dot(D, 0, { r: 8, fill: H.colors.good });
v.text("source", 5, 0.5, { color: H.colors.accent, size: 12 });
v.text("listener", D - 60, 0.5, { color: H.colors.good, size: 12 });
const arrived = vs * phase >= D;
H.text("Speed of sound:  v = sqrt(gamma R T / M)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("T = " + T.toFixed(0) + " K    v = " + vs.toFixed(1) + " m/s    travel time over " + D + " m = " + flight.toFixed(2) + " s" + (arrived ? "  ✓ heard" : ""), 24, 52, { color: H.colors.sub, size: 12 });
H.legend([{ label: "source", color: H.colors.accent }, { label: "pulse", color: H.colors.warn }, { label: "listener", color: H.colors.good }], H.W - 160, 28);
